-- Fundo Partidario anual (duodecimos) 2025 e 2026 por partido.
-- Fonte: planilhas oficiais do TSE (Partidos > Contas partidarias >
-- Fundo Partidario). Valor = total DISTRIBUIDO no ano (2026: jan-out).
-- Idempotente.

DELETE FROM "PartidoFundo" WHERE tipo = 'FUNDO_PARTIDARIO' AND ano IN (2025, 2026);

